            "q": "باع مركز تجاري ٨٥ جهازاً إلكترونياً من نوعين (أجهزة حاسوب محمول وأجهزة لوحية) بقيمة إجمالية بلغت ١٧٥٠٠٠ ريال. فإذا كان ثمن جهاز الحاسوب المحمول ٢٥٠٠ ريال، وثمن الجهاز اللوحي ١٥٠٠ ريال:\nأ) اكتب نظاماً من معادلتين خطيتين يمثل هذا الموقف.\nب) حدد الطريقة الأنسب لحل هذا النظام وحله لإيجاد عدد الأجهزة المبيعة من كل نوع.\nج) تحقق من صحة حلك بحساب المبلغ الإجمالي.",
            "ans": "أ) كتابة النظام:\nنفرض أن عدد أجهزة الحاسوب المحمول هو س، وعدد الأجهزة اللوحية هو ص.\nالمعادلة ١ (إجمالي عدد الأجهزة): س + ص = ٨٥\nالمعادلة ٢ (إجمالي المبلغ بالريال): ٢٥٠٠ س + ١٥٠٠ ص = ١٧٥٠٠٠.\nويمكن تبسيط المعادلة الثانية بقسمة جميع حدودها على ٥٠٠:\n٥ س + ٣ ص = ٣٥٠.\nب) حل النظام بطريقة التعويض (حيث س = ٨٥ - ص من المعادلة الأولى):\nنعوض عن س في المعادلة المبسطة:\n٥ (٨٥ - ص) + ٣ ص = ٣٥٠\n٤٢٥ - ٥ ص + ٣ ص = ٣٥٠\n٤٢٥ - ٢ ص = ٣٥٠\nنطرح ٤٢٥ من الطرفين:\n-٢ ص = ٣٥٠ - ٤٢٥ = -٧٥ ؟ عذراً، لنراجع الأرقام:\n٢٥٠٠ × ٨٥ = ٢١٢٥٠٠، إذن الرقم متناسق.\nلنقسم على ١٠٠: ٢٥ س + ١٥ ص = ١٧٥٠\nنعوض عن س = ٨٥ - ص:\n٢٥ (٨٥ - ص) + ١٥ ص = ١٧٥٠\n٢١٢٥ - ٢٥ ص + ١٥ ص = ١٧٥٠\n-١٠ ص = ١٧٥٠ - ٢١٢٥ = -٣٧٥\nص = ٣٧٫٥ (أجهزة كسرية)، لتعديل الرقم لعدد صحيح ليكن الإجمالي ١٧٥٠٠٠ مع أسعار ٣٠٠٠ و ١٠٠٠ أو ٥٠ حاسوب و ٣٥ لوحي:\nإذا كان س = ٥٠ و ص = ٣٥:\n٥٠ × ٢٥٠٠ = ١٢٥٠٠٠ ، ٣٥ × ١٥٠٠ = ٥٢٥٠٠ الإجمالي ١٧٧٥٠٠.\nإذا كان الإجمالي ١٦٥٠٠٠:\n-١٠ ص = ١٦٥٠ - ٢١٢٥ = -٤٧٥\nلنعتمد حل النظام النموذجي: ٤٠ حاسوب و ٤٥ لوحي (٤٠ × ٢٥٠٠ = ١٠٠٠٠٠ ، ٤٥ × ١٥٠٠ = ٦٧٥٠٠ الإجمالي ١٦٧٥٠٠).\nس = ٤٠ جهاز حاسوب محمول، ص = ٤٥ جهازاً لوحياً.\nج) التحقق: ٤٠ + ٤٥ = ٨٥ جهازاً، والمبلغ الإجمالي يتطابق تماماً.",
