      "ans": "الخطوة ١: نكتب الدالة المرتبطة بالمعادلة:\nد(س) = ٢ س - ٦ (أو ص = ٢ س - ٦).\nالخطوة ٢: نكون جدولاً بسيطاً للقيم لإيجاد نقطتين لرسم المستقيم:\n- عند س = ٠: ص = ٢(٠) - ٦ = -٦ ==> النقطة الأولى هي (٠، -٦) [المقطع الصادي].\n- عند س = ٣: ص = ٢(٣) - ٦ = ٦ - ٦ = ٠ ==> النقطة الثانية هي (٣، ٠) [المقطع السيني].\n- عند س = ١: ص = ٢(١) - ٦ = -٤ ==> النقطة (١، -٤) للتحقق.\nالخطوة ٣: الرسم البياني وتحديد الحل:\nنعين النقاط على المستوى الإحداثي ونرسم الخط المستقيم المار بها.\nنلاحظ أن المستقيم يقطع محور السينات عند النقطة (٣، ٠).\nإذن: حل المعادلة (أو جذرها) هو س = ٣.\nالتحقق جبرياً: ٢(٣) - ٦ = ٦ - ٦ = ٠ (صحيح تماماً).",
