      "q": "اكتب بصيغة الميل والمقطع معادلة المستقيم المار بالنقطة أ(٣، -٢) في الحالتين الآتيتين موضحاً الخطوات الرياضية كاملة:\nالحالة الأولى: إذا كان يوازي المستقيم ص = -٤ س + ٧.\nالحالة الثانية: إذا كان يعامد المستقيم ص = -٤ س + ٧.",
      "ans": "الحالة الأولى (الموازي):\n١) المستقيم المعطى ميله م١ = -٤.\n٢) بما أن المستقيم المطلوب موازٍ له، فإن ميله م = -٤.\n٣) نجد المقطع الصادي ب بالتعويض بالنقطة أ(٣، -٢) والميل م = -٤ في ص = م س + ب:\n-٢ = -٤(٣) + ب ==> -٢ = -١٢ + ب ==> ب = -٢ + ١٢ = ١٠.\n٤) معادلة المستقيم الموازي هي: ص = -٤ س + ١٠.\n\nالحالة الثانية (المتعامد):\n١) ميل المستقيم المعامد م = المعكوس المقلوب لـ (-٤) = +١ ÷ ٤.\n٢) نجد المقطع الصادي ب بالتعويض بالنقطة أ(٣، -٢) والميل م = ١ ÷ ٤:\n-٢ = (١ ÷ ٤)(٣) + ب ==> -٢ = (٣ ÷ ٤) + ب ==> ب = -٢ - (٣ ÷ ٤) = -١١ ÷ ٤.\n٣) معادلة المستقيم المعامد هي: ص = (١ ÷ ٤) س - (١١ ÷ ٤).",
