      "ans": "لحساب ميول الأضلاع الأربعة:\n١) ميل الضلع أ ب: م(أ ب) = (٣ - ١) ÷ (٥ - ١) = ٢ ÷ ٤ = ١ ÷ ٢.\n٢) ميل الضلع ب جـ: م(ب جـ) = (٥ - ٣) ÷ (٤ - ٥) = ٢ ÷ (-١) = -٢.\n٣) ميل الضلع جـ د: م(جـ د) = (٣ - ٥) ÷ (٠ - ٤) = -٢ ÷ (-٤) = ١ ÷ ٢.\n٤) ميل الضلع د أ: م(د أ) = (١ - ٣) ÷ (١ - ٠) = -٢ ÷ ١ = -٢.\nالاستنتاج والتبرير:\n- نلاحظ أن م(أ ب) = م(جـ د) = ١ ÷ ٢، إذن الضلعان أ ب و جـ د متوازيان.\n- ونلاحظ أن م(ب جـ) = م(د أ) = -٢، إذن الضلعان ب جـ و د أ متوازيان، فالشكل متوازي أضلاع.\n- ونلاحظ أن م(أ ب) × م(ب جـ) = (١ ÷ ٢) × (-٢) = -١، إذن الضلعان المتجاوران متعامدان والزوايا قائمة.\nبما أن كل ضلعين متقابلين متوازيان وزواياه الأربع قوائم، إذن الشكل الرباعي أ ب جـ د يمثل مستطيلاً بالتأكيد.",
