      "q": "يقود خالد شاحنة نقل لا تتجاوز حمولتها القصوى المسموح بها نظاماً ٣٥٠٠ كجم. فإذا كانت الشاحنة فارغة تزن ٢١٠٠ كجم:\nأ) اكتب متباينة خطية تمثل أقصى وزن للبضائع (ب) يمكن لخالد تحميلها.\nب) حل المتباينة واكتب النتيجة بالصفة المميزة.\nج) هل يمكن لخالد تحميل بضائع وزنها ١٥٠٠ كجم؟ وضح إجابتك رياضياً.",
