      "ans": "الخطوة ١: حل المتباينة:\n-٦ س ≤ ٤٢\nنقسم طرفي المتباينة على معامل س وهو (-٦).\nالتبرير الرياضي: بما أننا نقسم على عدد سالب (-٦ < ٠)، فإن خاصية القسمة في التباين تقتضي عكس اتجاه إشارة التباين فوراً من (≤) إلى (≥):\n-٦ س ÷ (-٦) ≥ ٤٢ ÷ (-٦)\nس ≥ -٧.\nالخطوة ٢: كتابة مجموعة الحل:\nبالصفة المميزة: {س | س ≥ -٧}.\nالخطوة ٣: التمثيل البياني على خط الأعداد:\nنرسم خط الأعداد، ونعين النقطة -٧ ونضع عندها دائرة مغلقة (مظللة بالكامل لوجود علامة المساواة)، ثم نرسم سهماً مظللاً يتجه إلى اليمين ليشمل جميع الأعداد الأكبر من أو تساوي -٧.",
