      "q": "يريد متطوع توزيع وجبات إفطار صائم، فإذا كانت تكلفة الوجبة الواحدة ٨ ريالات، ولديه ميزانية لا تتجاوز ١٢٠٠ ريال:\nأ) اكتب متباينة تمثل أكبر عدد من الوجبات (و) يمكن للمتطوع إعدادها.\nب) حل المتباينة ومثلها بيانياً.\nج) إذا قرر زيادة تكلفة الوجبة بإضافة عصير قيمته ريالان لكل وجبة، فما أكبر عدد من الوجبات يمكنه توفيره الآن؟",
