      "lessonTitle": "حل المتباينات التي تتضمن القيمة المطلقة",
      "q": "في أحد مصانع الأدوية، يُشترط أن تكون كتلة القرص الدوائي ٣٥٠ ملجم مع نسبة تفاوت مسموح بها لا تزيد عن ٧ ملجم لضمان سلامة المرضى.\nأ) اكتب متباينة تتضمن قيمة مطلقة تصف مدى الكتلة المقبولة للقرص (ك).\nب) حل المتباينة لإيجاد الحدين الأدنى والأعلى لكتلة القرص الدوائي.\nج) إذا تم فحص قرص دوائي ووجدت كتلته ٣٤١ ملجم، فهل يُقبل هذا القرص أم يُرفض؟ علل إجابتك رياضياً.",
      "ans": "أ) كتابة المتباينة:\nالمسافة بين الكتلة الفعلية (ك) والكتلة المستهدفة (٣٥٠) لا تتجاوز ٧ ملجم:\n|ك - ٣٥٠| ≤ ٧.\nب) حل المتباينة:\nالمتباينة محصورة برابط 'و':\n-٧ ≤ ك - ٣٥٠ ≤ ٧\nنضيف ٣٥٠ للأطراف الثلاثة:\n٣٥٠ - ٧ ≤ ك ≤ ٣٥٠ + ٧\n٣٤٣ ≤ ك ≤ ٣٥٧ ملجم.\nإذن: الحد الأدنى المقبول لكتلة القرص هو ٣٤٣ ملجم، والحد الأعلى المقبول هو ٣٥٧ ملجم.\nج) فحص القرص ذي الكتلة ٣٤١ ملجم:\nبما أن ٣٤١ ملجم < ٣٤٣ ملجم (أقل من الحد الأدنى المسموح به)، فإن هذا القرص يُرفض حتماً لعدم مطابقته لمعايير الجودة والسلامة الدوائية المعتمدة.",
      "difficulty": "متقدم",
