      "ans": "الخطوة ١: تحليل المعادلتين بصيغة الميل والمقطع:\n- المعادلة الأولى (ص = -٢ س + ٥): م١ = -٢، ب١ = ٥. يمر بالنقطة (٠، ٥) والنقطة (١، ٣) والنقطة (٢، ١).\n- المعادلة الثانية (ص = س - ١): م٢ = ١، ب٢ = -١. يمر بالنقطة (٠، -١) والنقطة (١، ٠) والنقطة (٢، ١).\nالخطوة ٢: التمثيل البياني:\nنعين النقاط لكل مستقيم ونرسم الخطين في المستوى الإحداثي.\nالخطوة ٣: تحديد نقطة التقاطع والحل:\nنلاحظ من التمثيل والجدول أن المستقيمين يتقاطعان تماماً في النقطة المشتركة (٢، ١).\nإذن: حل النظام هو الزوج المرتب (٢، ١).\nالخطوة ٤: التحقق جبرياً:\n- في الأولى: ١ = -٢(٢) + ٥ = -٤ + ٥ = ١ (صحيح).\n- في الثانية: ١ = ٢ - ١ = ١ (صحيح).\nالخطوة ٥: تصنيف النظام: متسق ومستقل (له حل وحيد).",
