      "q": "صنف كل نظام من أنظمة المعادلات الخطية الآتية إلى (متسق ومستقل، متسق وغير مستقل، غير متسق) مع ذكر عدد الحلول والتعليل الرياضي دون رسم بياني:\nأ) ص = ٤ س - ٦   و   ص = ٤ س + ٣\nب) ٢ س + ص = ٥   و   ص = -٢ س + ٥\nج) ص = ٣ س + ١   و   ص = -س + ٥",
      "ans": "أ) النظام الأول: ص = ٤ س - ٦ و ص = ٤ س + ٣:\nنلاحظ أن الميلين متساويان (م١ = م٢ = ٤) والمقطعين الصاديين مختلفان (ب١ = -٦ ، ب٢ = ٣).\nالتعليل: المستقيمان متوازيان ولا يلتقيان في أي نقطة.\nالتصنيف: غير متسق، عدد الحلول: لا يوجد حل (المجموعة الخالية ∅).\n\nب) النظام الثاني: ٢ س + ص = ٥ و ص = -٢ س + ٥:\nبإعادة كتابة الأولى: ص = -٢ س + ٥.\nنلاحظ أن المعادلتين متطابقتان تماماً؛ لهما نفس الميل (م = -٢) ونفس المقطع الصادي (ب = ٥).\nالتعليل: المستقيمان منطبقان على بعضهما تماماً.\nالتصنيف: متسق وغير مستقل، عدد الحلول: عدد لا نهائي من الحلول.\n\nج) النظام الثالث: ص = ٣ س + ١ و ص = -س + ٥:\nنلاحظ أن الميلين مختلفان (م١ = ٣ ، م٢ = -١).\nالتعليل: المستقيمان يتقاطعان في نقطة واحدة وحيدة.\nالتصنيف: متسق ومستقل، عدد الحلول: حل واحد فقط.",
