      "ans": "الخطوة ١: عزل المتغير ذي المعامل ١:\nنلاحظ أن المتغير ص في المعادلة الأولى معامله ١، فنعزله بنقل ٢ س للطرف الآخر:\nص = ٩ - ٢ س  (المعادلة المساعدة).\nالخطوة ٢: التعويض في المعادلة الثانية:\nنعوض عن ص بالعبارة (٩ - ٢ س) في المعادلة الثانية:\n٣ س + ٤ (٩ - ٢ س) = ١٦\nنوزع الضرب على القوس:\n٣ س + ٣٦ - ٨ س = ١٦\nنجمع الحدود المتشابهة:\n-٥ س + ٣٦ = ١٦\nنطرح ٣٦ من الطرفين:\n-٥ س = ١٦ - ٣٦ = -٢٠\nنقسم على -٥:\nس = -٢٠ ÷ (-٥) = ٤.\nالخطوة ٣: التعويض العكسي لإيجاد قيمة ص:\nنعوض عن س = ٤ في المعادلة المساعدة:\nص = ٩ - ٢(٤) = ٩ - ٨ = ١.\nالخطوة ٤: كتابة الحل والتحقق:\nحل النظام هو الزوج المرتب: (٤، ١).\nالتحقق بالتعويض في المعادلة الثانية الأصلية:\n٣(٤) + ٤(١) = ١٢ + ٤ = ١٦ (صحيح تماماً ومطابق للطرف الأيسر).",
