      "ans": "الخطوة ١: تحديد المتغير والمعاملات:\nنلاحظ أن معاملي ص هما +٣ و -٣ (معكوسان جمعياً ونظيران لبعضهما).\nالخطوة ٢: تطبيق الحذف بالجمع:\nنجمع المعادلتين رأسياً:\n(٥ س + ٢ س) + (٣ ص - ٣ ص) = -١ + ١٥\n٧ س + ٠ = ١٤\n٧ س = ١٤\nنقسم على ٧:\nس = ١٤ ÷ ٧ = ٢.\nالخطوة ٣: التعويض لإيجاد ص:\nنعوض عن س = ٢ في المعادلة الأولى:\n٥(٢) + ٣ ص = -١\n١٠ + ٣ ص = -١\nنطرح ١٠ من الطرفين:\n٣ ص = -١ - ١٠ = -١١ ؟ عذراً، لنعد الحساب:\n-١ + ١٥ = ١٤، س = ٢.\n٥(٢) + ٣ ص = -١ ==> ١٠ + ٣ ص = -١ ==> ٣ ص = -١ - ١٠ = -١١ (كسر).\nأو نعوض في الثانية للتحقق: ٢(٢) - ٣ ص = ١٥ ==> ٤ - ٣ ص = ١٥ ==> -٣ ص = ١١ ==> ص = -١١ ÷ ٣.\nإذن حل النظام هو الزوج المرتب: (٢، -١١ ÷ ٣).\nالتحقق بالمعادلتين سليم.",
