      "ans": "أ) كتابة النظام:\nفي اتجاه الريح (الرياح تدفع الطائرة فتجمع السرعتان):\nط + ر = ٨٤٠  (المعادلة ١)\nضد اتجاه الريح (الرياح تقاوم الطائرة فتطرح السرعتان):\nط - ر = ٧٦٠  (المعادلة ٢)\nب) حل النظام بالحذف:\nنلاحظ أن معاملي ر متعاكسان (+١ و -١)، فنجمع المعادلتين بالجمع لحذف ر:\n(ط + ط) + (ر - ر) = ٨٤٠ + ٧٦٠\n٢ ط = ١٦٠٠\nبقسمة الطرفين على ٢:\nط = ١٦٠٠ ÷ ٢ = ٨٠٠ كم/ساعة هي سرعة الطائرة في الهواء الساكن.\nنعوض عن ط = ٨٠٠ في المعادلة الأولى لإيجاد ر:\n٨٠٠ + ر = ٨٤٠\nر = ٨٤٠ - ٨٠٠ = ٤٠ كم/ساعة هي سرعة الرياح.\nإذن: سرعة الطائرة في الهواء الساكن = ٨٠٠ كم/س، وسرعة الرياح = ٤٠ كم/س.",
