      "ans": "الخطوة ١: اختيار المتغير وإيجاد المضاعف المشترك:\nنختار حذف المتغير س. معاملا س هما ٣ و ٢، والمضاعف المشترك الأصغر لهما هو ٦.\nلذلك سنضرب المعادلة الأولى في ٢ لتصبح معامِلتها +٦ س، ونضرب المعادلة الثانية في (-٣) لتصبح معامِلتها -٦ س (معكوس جمعي).\nالخطوة ٢: ضرب المعادلتين:\n٢ (٣ س + ٤ ص = ١١) ==> ٦ س + ٨ ص = ٢٢  (المعادلة ٣)\n-٣ (٢ س + ٥ ص = ١٢) ==> -٦ س - ١٥ ص = -٣٦  (المعادلة ٤)\nالخطوة ٣: جمع المعادلتين (٣) و (٤) لحذف س:\n(٦ س - ٦ س) + (٨ ص - ١٥ ص) = ٢٢ - ٣٦\n٠ - ٧ ص = -١٤\n-٧ ص = -١٤\nنقسم على -٧:\nص = -١٤ ÷ (-٧) = ٢.\nالخطوة ٤: التعويض لإيجاد قيمة س:\nنعوض عن ص = ٢ في المعادلة الأولى الأصلية:\n٣ س + ٤(٢) = ١١\n٣ س + ٨ = ١١\nنطرح ٨ من الطرفين: ٣ س = ٣ ==> س = ١.\nالخطوة ٥: كتابة الحل والتحقق:\nحل النظام هو الزوج المرتب: (١، ٢).\nالتحقق في المعادلة الثانية: ٢(١) + ٥(٢) = ٢ + ١٠ = ١٢ (صحيح ومطابق للطرف الأيسر).",
