      "q": "حدد الطريقة الأنسب لحل كل نظام مما يأتي مع ذكر التعليل الرياضي الدقيق لاختيارك، ثم اختر أحد النظامين وحله بالتفصيل:\nالنظام (أ): ص = ٢ س - ٥   و   ٣ س + ٤ ص = ٢٤\nالنظام (ب): ٥ س + ٦ ص = ١٤   و   ٣ س - ٦ ص = ٢",
