      "q": "قام كيميائي بخلط محلولين من حمض الهيدروكلوريك؛ الأول تركيزه ١٠٪ والثاني تركيزه ٣٠٪ للحصول على ٦٠ لتراً من محلول جديد تركيزه ٢٥٪.\nأ) اكتب نظاماً من معادلتين يمثل كمية كل من المحلولين وكمية الحمض الخالص.\nب) حل النظام لإيجاد عدد اللترات الواجب أخذها من كل محلول.",
      "ans": "أ) كتابة النظام:\nنفرض أن عدد لترات المحلول الأول (تركيز ١٠٪) هو س.\nونفرض أن عدد لترات المحلول الثاني (تركيز ٣٠٪) هو ص.\nالمعادلة ١ (إجمالي حجم المحلول): س + ص = ٦٠.\nالمعادلة ٢ (كمية الحمض الخالص):\n٠٫١٠ س + ٠٫٣٠ ص = ٠٫٢٥ × ٦٠ = ١٥ لتراً من الحمض الخالص.\nب) حل النظام:\nمن المعادلة الأولى: س = ٦٠ - ص.\nنعوض في المعادلة الثانية:\n٠٫١٠ (٦٠ - ص) + ٠٫٣٠ ص = ١٥\n٦ - ٠٫١٠ ص + ٠٫٣٠ ص = ١٥\n٦ + ٠٫٢٠ ص = ١٥\nنطرح ٦ من الطرفين:\n٠٫٢٠ ص = ٩\nنقسم على ٠٫٢٠:\nص = ٩ ÷ ٠٫٢٠ = ٤٥ لتراً من المحلول الثاني (تركيز ٣٠٪).\nنعوض لإيجاد س:\nس = ٦٠ - ٤٥ = ١٥ لتراً من المحلول الأول (تركيز ١٠٪).\nإذن: يجب خلط ١٥ لتراً من المحلول ذي التركيز ١٠٪ مع ٤٥ لتراً من المحلول ذي التركيز ٣٠٪ للحصول على ٦٠ لتراً بتركيز ٢٥٪.",
